#!/usr/bin/env python3
"""Fault each real vector member decoder and restore exact generated bytes."""
import os
from pathlib import Path
import re
import subprocess

crate = Path(__file__).resolve().parents[1]
logs = crate.parent / 'target/position-risk-alias-controls'
logs.mkdir(parents=True, exist_ok=True)
before = b'struct GetPositionRiskResponseRowWire {\n    #[serde(rename = "symbol")]'
after = b'struct GetPositionRiskResponseRowWire {\n    #[serde(rename = "control_symbol")]'
cases = [
    ('futures', 'binance.rs', 'futures_risk_vector_alias_preserves_native_rows',
     'actual Futures vector alias decodes source rows'),
    ('pm', 'binancepm.rs', 'pm_risk_vector_alias_preserves_native_rows',
     'actual PM vector alias decodes source rows'),
]


def execute(label, name):
    path = logs / (label + '.log')
    command = ['cargo', '+1.99.0', 'test', '--color', 'never', '--locked', '--jobs', '1',
               '-p', 'safe-cex-venue-binance', '--test', 'accepted_record_shapes',
               name, '--', '--exact']
    with path.open('w') as output:
        result = subprocess.run(command, cwd=crate.parent,
                                env={**os.environ, 'CARGO_BUILD_JOBS': '1'},
                                stdout=output, stderr=subprocess.STDOUT)
    return result.returncode, path.read_text()


for label, file, name, assertion in cases:
    source = crate / 'src/generated' / file
    original = source.read_bytes()
    assert original.count(before) == 1, label
    try:
        source.write_bytes(original.replace(before, after))
        status, log = execute(label + '-red', name)
        assert status != 0 and f'test {name} ... FAILED' in log, log[-5000:]
        assert not re.search(r'^error(?:\[|: (?!test failed\b))', log, re.M), log[-5000:]
        assert assertion in log and 'control_symbol' in log, log[-5000:]
    finally:
        source.write_bytes(original)
        assert source.read_bytes() == original
    status, log = execute(label + '-restored', name)
    assert status == 0 and '1 passed; 0 failed' in log, log[-5000:]
    print(f'{label}: compiled actual-decoder RED; exact restoration GREEN.', flush=True)
